<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import Button from 'primevue/button'
import Drawer from 'primevue/drawer'
import Dialog from 'primevue/dialog'
import InputText from 'primevue/inputtext'
import Select from 'primevue/select'
import Message from 'primevue/message'
import { AgGridVue } from 'ag-grid-vue3'
import { AllCommunityModule, ModuleRegistry, themeQuartz, type ColDef } from 'ag-grid-community'
import { authService, type FormOption } from '@/modules/security/services/auth.service'
import { createStandardGridOptions } from '@/utils/ag-grid'
import { useObjectPermissions } from '@/composables/use-object-permissions'
ModuleRegistry.registerModules([AllCommunityModule])
const rows = ref<FormOption[]>([]), loading = ref(false), saving = ref(false), error = ref(''), filtersVisible = ref(false), filterName = ref(''), filterApplication = ref<string | null>(null), filterModule = ref<string | null>(null), filterMenu = ref<string | null>(null), filterSubmenu = ref<string | null>(null), dialogVisible = ref(false), deleteVisible = ref(false), selected = ref<FormOption | null>(null)
const form = ref({ id: '', submenuId: null as string | null, secondLevelId: null as string | null, code: '', name: '', description: '', color: '', icon: '', status: 'A' })
const { can } = useObjectPermissions('form-options')
const canUpdate = can('update'), canDelete = can('delete')
const codeError = computed(() => !form.value.code.trim() ? 'El código es obligatorio.' : form.value.code.trim().length > 50 ? 'El código no puede superar 50 caracteres.' : '')
const uniqueLabels = (key: keyof FormOption) => [{ label: 'Todos', value: null }, ...Array.from(new Set(rows.value.map(row => row[key]).filter(Boolean))).map(value => ({ label: String(value), value: String(value) }))]
const applicationOptions = computed(() => uniqueLabels('applicationName')), moduleOptions = computed(() => uniqueLabels('moduleName')), menuOptions = computed(() => uniqueLabels('menuName')), submenuOptions = computed(() => uniqueLabels('submenuName'))
const filteredRows = computed(() => rows.value.filter(row => (!filterApplication.value || row.applicationName === filterApplication.value) && (!filterModule.value || row.moduleName === filterModule.value) && (!filterMenu.value || row.menuName === filterMenu.value) && (!filterSubmenu.value || row.submenuName === filterSubmenu.value)))
const gridTheme = themeQuartz.withParams({ accentColor: '#16457f', borderColor: '#d7e4f0', headerBackgroundColor: '#f4f8fc', headerTextColor: '#38536f', fontFamily: 'Manrope, sans-serif', wrapperBorderRadius: 0 })
const columns = computed<ColDef<FormOption>[]>(() => [
  { field: 'applicationName', headerName: 'Aplicación', minWidth: 180, flex: 1, filter: 'agTextColumnFilter' },
  { field: 'moduleName', headerName: 'Módulo', minWidth: 170, flex: .9, filter: 'agTextColumnFilter' },
  { field: 'menuName', headerName: 'Menú', minWidth: 150, flex: .8, filter: 'agTextColumnFilter' },
  { field: 'submenuName', headerName: 'Submenú', minWidth: 190, flex: 1, filter: 'agTextColumnFilter' },
  { field: 'code', headerName: 'Código', minWidth: 160, flex: .9, filter: 'agTextColumnFilter' },
  { field: 'name', headerName: 'Opción', minWidth: 180, flex: 1, filter: 'agTextColumnFilter' },
  { field: 'description', headerName: 'Descripción', minWidth: 180, flex: 1, filter: 'agTextColumnFilter' },
  { field: 'status', headerName: 'Estado', minWidth: 110, valueFormatter: ({ value }) => value === 'A' ? 'Activo' : 'Inactivo', filter: 'agTextColumnFilter' },
  { headerName: 'Acciones', sortable: false, filter: false, pinned: 'right', width: 105, cellRenderer: () => `<div class="company-actions">${canUpdate.value ? '<button data-action="edit"><i class="pi pi-pencil"></i></button>' : ''}${canDelete.value ? '<button data-action="delete"><i class="pi pi-trash"></i></button>' : ''}</div>` },
])
async function load() { loading.value = true; try { rows.value = await authService.listFormOptionsMaintenance({ name: filterName.value || undefined }) } catch (reason) { error.value = reason instanceof Error ? reason.message : 'No fue posible cargar las opciones.' } finally { loading.value = false } }
function openEdit(row: FormOption) { selected.value = row; form.value = { id: row.id, submenuId: row.submenuId ?? null, secondLevelId: row.secondLevelSubmenuId ?? null, code: row.code ?? '', name: row.name ?? '', description: row.description ?? '', color: row.color ?? '', icon: row.icon ?? '', status: row.status }; dialogVisible.value = true }
function onCellClicked(event: { event?: Event; data?: FormOption }) { const action = (event.event?.target as HTMLElement | null)?.closest<HTMLElement>('[data-action]')?.dataset.action; if (!event.data) return; if (action === 'edit' && canUpdate.value) openEdit(event.data); if (action === 'delete' && canDelete.value) { selected.value = event.data; deleteVisible.value = true } }
async function save() { if (!form.value.id || codeError.value) return; saving.value = true; try { await authService.updateFormOption(form.value.id, { submenuId: form.value.submenuId, secondLevelId: form.value.secondLevelId, code: form.value.code.trim(), name: form.value.name, description: form.value.description, color: form.value.color || null, icon: form.value.icon || null, status: form.value.status }); dialogVisible.value = false; await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'No fue posible guardar.' } finally { saving.value = false } }
async function remove() { if (!selected.value) return; saving.value = true; try { await authService.deleteFormOption(selected.value.id); deleteVisible.value = false; await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'No fue posible dar de baja.' } finally { saving.value = false } }
onMounted(load)
</script>
<template>
  <section class="companies-view"><header class="companies-view__header"><div><h1>Opciones de formulario</h1><p>Administración de controles y acciones disponibles por vista.</p></div><div class="companies-view__actions"><Button label="Nuevo" icon="pi pi-plus" class="company-primary-button"/><Button label="Filtros" icon="pi pi-filter" class="company-secondary-button" outlined @click="filtersVisible=true"/></div></header><Message v-if="error" severity="error" closable @close="error=''">{{ error }}</Message><section class="companies-table-card"><div class="companies-table-card__toolbar"><span class="companies-table-card__title">Listado de opciones</span></div><AgGridVue v-bind="createStandardGridOptions<FormOption>()" class="companies-grid" :theme="gridTheme" :row-data="filteredRows" :column-defs="columns" :loading="loading" :default-col-def="{sortable:true,resizable:true,filter:true}" :dom-layout="'autoHeight'" @cell-clicked="onCellClicked"/></section><Drawer v-model:visible="filtersVisible" position="right" class="companies-filter-drawer"><template #header><strong>Filtros de consulta</strong></template><div class="companies-filter-form"><label>Aplicación</label><Select v-model="filterApplication" :options="applicationOptions" option-label="label" option-value="value" fluid/><label>Módulo</label><Select v-model="filterModule" :options="moduleOptions" option-label="label" option-value="value" fluid/><label>Menú</label><Select v-model="filterMenu" :options="menuOptions" option-label="label" option-value="value" fluid/><label>Submenú</label><Select v-model="filterSubmenu" :options="submenuOptions" option-label="label" option-value="value" fluid/><label>Nombre o código</label><InputText v-model="filterName" fluid/></div><template #footer><div class="companies-filter-actions"><Button label="Limpiar" class="company-secondary-button" text @click="filterName='';filterApplication=null;filterModule=null;filterMenu=null;filterSubmenu=null"/><Button label="Aplicar filtros" class="company-primary-button" @click="filtersVisible=false;load()"/></div></template></Drawer><Dialog v-model:visible="dialogVisible" modal header="Editar opción" class="company-dialog"><div class="company-form"><label>Código</label><InputText v-model="form.code" maxlength="50" fluid/><small v-if="codeError" class="form-field-error">{{ codeError }}</small><label>Opción</label><InputText v-model="form.name" fluid/><label>Descripción</label><InputText v-model="form.description" fluid/><label>Estado</label><Select v-model="form.status" :options="[{label:'Activo',value:'A'},{label:'Inactivo',value:'I'}]" option-label="label" option-value="value" fluid/></div><template #footer><Button label="Cancelar" class="company-secondary-button" text @click="dialogVisible=false"/><Button label="Guardar" class="company-primary-button" :loading="saving" :disabled="Boolean(codeError)" @click="save"/></template></Dialog><Dialog v-model:visible="deleteVisible" modal header="Confirmar baja" class="company-dialog"><p>¿Dar de baja a <strong>{{ selected?.name }}</strong>?</p><template #footer><Button label="Cancelar" text @click="deleteVisible=false"/><Button label="Dar de baja" severity="danger" :loading="saving" @click="remove"/></template></Dialog></section>
</template>
